INSERT INTO changelog (title, body, created_at) VALUES ('Оплата однією кнопкою з Telegram', 'У ранковому зведенні під кожною оплатою, що вже мала прийти (до 3), є кнопка «💸 Оплатив: клієнт сума» — натиснув, і оплата записана сьогоднішнім днем у Гроші. Так дохід за місяць рахується по-справжньому, без входу в систему. Інша сума чи частина — скажи Джері: «Аква Віта заплатила 450».', datetime('now'));
